package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute ledOn : Boolean := false;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_1;
      then if accumulatedMs >= 1000 {
        first start;
        then assign accumulatedMs := accumulatedMs - 1000;
        then assign ledOn := not ledOn;
      }
    }
    out attribute io_0 : Boolean = ledOn;
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Boolean = false;
  }
  part system : Controller;
}
